document.addEventListener('DOMContentLoaded', function() {

    // ===== BUTTON STATE MANAGEMENT UTILITY =====
    function setButtonState(btn, state, text) {
        btn.classList.remove('cin-btn-loading', 'cin-btn-success', 'cin-btn-error');
        
        // Handle both input and button elements
        const isInputElement = btn.tagName === 'INPUT';
        const getButtonText = () => isInputElement ? btn.value : btn.textContent;
        const setButtonText = (t) => {
            if (isInputElement) btn.value = t;
            else btn.textContent = t;
        };
        
        if (state === 'loading') {
            btn.disabled = true;
            btn.classList.add('cin-btn-loading');
            btn.setAttribute('data-original-text', getButtonText());
            setButtonText(text || 'Processing...');
        } else if (state === 'success') {
            btn.disabled = true;
            btn.classList.add('cin-btn-success');
            setButtonText(text || 'Success!');
        } else if (state === 'error') {
            btn.disabled = true;
            btn.classList.add('cin-btn-error');
            setButtonText(text || 'Failed');
        } else if (state === 'reset') {
            btn.disabled = false;
            // If text is explicitly provided, use it; otherwise use data-original-text
            setButtonText(text || btn.getAttribute('data-original-text') || 'Submit');
            btn.removeAttribute('data-original-text');
        }
    }

    // ===== CHECK FOR SETTINGS SAVED MESSAGE =====
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('settings-updated') === 'true') {
        if (typeof window.cinShowMessage === 'function') {
            window.cinShowMessage('Settings saved successfully!', 'success');
        }
    }

    // ===== TEST CRM CONNECTION =====
    const testBtn = document.getElementById('cin-test-crm-btn');
    if (testBtn) {
        testBtn.addEventListener('click', function(e) {
            e.preventDefault();
            
            const endpoint = document.getElementById('crm_endpoint')?.value;
            
            if (!endpoint) {
                if (typeof window.cinShowMessage === 'function') {
                    window.cinShowMessage('Endpoint is required.', 'error');
                }
                return;
            }
            
            setButtonState(testBtn, 'loading', 'Testing Connection...');
            
            fetch(window.cinCRMSettings.ajaxUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded'
                },
                body: new URLSearchParams({
                    action: 'ci_test_crm_connection',
                    nonce: window.cinCRMSettings.nonce,
                    endpoint: endpoint
                })
            })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    setButtonState(testBtn, 'success', 'Connected!');
                    if (typeof window.cinShowMessage === 'function') {
                        window.cinShowMessage(data.data.message, 'success');
                    }
                } else {
                    setButtonState(testBtn, 'error', 'Connection Failed');
                    if (typeof window.cinShowMessage === 'function') {
                        window.cinShowMessage(data.data.message, 'error');
                    }
                }
                setTimeout(() => setButtonState(testBtn, 'reset', 'Test Connection'), 2000);
            })
            .catch(err => {
                setButtonState(testBtn, 'error', 'Error');
                if (typeof window.cinShowMessage === 'function') {
                    window.cinShowMessage('Error: ' + err.message, 'error');
                }
                setTimeout(() => setButtonState(testBtn, 'reset', 'Test Connection'), 2000);
            });
        });
    }

    // ===== TOGGLE CRM SERVICE (Using Global Toggle Utility) =====
    if (typeof window.cinInitToggleButton === 'function') {
        window.cinInitToggleButton({
            buttonId: 'cin-toggle-crm-service',
            statusLabelId: 'cin-crm-status-label',
            hiddenFieldId: null,
            ajaxAction: 'ci_toggle_crm_service',
            enabledText: 'Disable Salesforce Sync',
            disabledText: 'Enable Salesforce Sync',
            enabledLabel: 'Service Enabled',
            disabledLabel: 'Service Disabled',
            onToggle: function(enabled) {
                // Any additional CRM-specific logic can go here
            }
        });
    }

    // ===== CONNECT TO SALESFORCE WITH AUTO-SAVE =====
    const connectBtn = document.getElementById('cin-connect-crm-btn');
    if (connectBtn) {
        connectBtn.addEventListener('click', function(e) {
            e.preventDefault();
            
            const consumerKey = document.getElementById('salesforce_consumer_key')?.value?.trim();
            const consumerSecret = document.getElementById('salesforce_consumer_secret')?.value?.trim();
            
            // Validate Consumer Key
            if (!consumerKey) {
                if (typeof window.cinShowMessage === 'function') {
                    window.cinShowMessage('Please enter your Consumer Key before connecting.', 'error');
                }
                document.getElementById('salesforce_consumer_key').focus();
                return;
            }
            
            const btn = this;
            setButtonState(btn, 'loading', 'Saving Credentials...');
            
            // Save credentials via AJAX before redirecting
            const formData = new FormData();
            formData.append('action', 'ci_save_oauth_credentials');
            formData.append('nonce', window.cinCRMSettings.nonce);
            formData.append('consumer_key', consumerKey);
            formData.append('consumer_secret', consumerSecret);
            
            fetch(window.cinCRMSettings.ajaxUrl, {
                method: 'POST',
                body: formData
            })
            .then(res => res.json())
            .then(data => {
                if (data.success) {
                    setButtonState(btn, 'success', 'Redirecting to Salesforce...');
                    // Redirect to OAuth URL with fresh credentials
                    setTimeout(() => {
                        window.location.href = data.data.oauth_url;
                    }, 800);
                } else {
                    setButtonState(btn, 'error', 'Save Failed');
                    if (typeof window.cinShowMessage === 'function') {
                        window.cinShowMessage(data.data.message || 'Error saving credentials', 'error');
                    }
                    setTimeout(() => setButtonState(btn, 'reset', 'Connect to Salesforce'), 2000);
                }
            })
            .catch(err => {
                setButtonState(btn, 'error', 'Error');
                if (typeof window.cinShowMessage === 'function') {
                    window.cinShowMessage('Error: ' + err.message, 'error');
                }
                setTimeout(() => setButtonState(btn, 'reset', 'Connect to Salesforce'), 2000);
            });
        });
    }

    // ===== DISCONNECT FROM SALESFORCE =====
    jQuery(document).ready(function($) {
        $('#cin-disconnect-crm-btn').on('click', function() {
            if (!confirm('Are you sure you want to disconnect from Salesforce?')) {
                return;
            }
            
            const btn = this;
            setButtonState(btn, 'loading', 'Disconnecting...');
            
            $.post(ajaxurl, {
                action: 'ci_disconnect_crm',
                nonce: window.cinCRMSettings.nonce
            }, function(response) {
                if (response.success) {
                    setButtonState(btn, 'success', 'Disconnected!');
                    if (typeof window.cinShowMessage === 'function') {
                        window.cinShowMessage(response.data.message, 'success');
                    }
                    setTimeout(function() {
                        location.reload();
                    }, 1500);
                } else {
                    setButtonState(btn, 'error', 'Disconnect Failed');
                    if (typeof window.cinShowMessage === 'function') {
                        window.cinShowMessage(response.data.message, 'error');
                    }
                    setTimeout(() => setButtonState(btn, 'reset', 'Disconnect from Salesforce'), 2000);
                }
            });
        });
    });

});

// ===== COPY TO CLIPBOARD UTILITY =====
window.copyToClipboard = function(btn, text) {
    if (navigator.clipboard && window.isSecureContext) {
        // Use modern Clipboard API
        navigator.clipboard.writeText(text).then(function() {
            const originalText = btn.textContent;
            btn.textContent = 'Copied!';
            btn.style.backgroundColor = '#28a745';
            btn.style.borderColor = '#28a745';
            btn.style.color = 'white';
            
            setTimeout(function() {
                btn.textContent = originalText;
                btn.style.backgroundColor = '';
                btn.style.borderColor = '';
                btn.style.color = '';
            }, 2000);
        });
    } else {
        // Fallback for older browsers
        const textarea = document.createElement('textarea');
        textarea.value = text;
        textarea.style.position = 'fixed';
        textarea.style.opacity = '0';
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand('copy');
        document.body.removeChild(textarea);
        
        btn.textContent = 'Copied!';
        setTimeout(function() {
            btn.textContent = 'Copy URL';
        }, 2000);
    }
};
